// Capture the component stack of a React render loop, because nothing else can.
//
// WHY THIS EXISTS
// A render loop pins the main thread and allocates until the OOM killer intervenes — measured
// 2026-08-31 at 27.50 GB RSS / 128 GB VmPeak / 114% CPU, reached in about two minutes, with the box
// down to 0.6 GB free. React names the responsible component in the error's COMPONENT STACK, and that
// stack is unreachable here:
//
//   • Vite's client forwards only the MESSAGE to the app log. Verified against the full untruncated
//     line — the stack is not in it.
//   • WebKitGTK exposes no usable inspector, so the browser console cannot be opened either.
//   • The app's own perf sampler is blind to it: the main thread is pinned, so nothing is sampled
//     DURING the loop. The last reading before one freeze was a normal `3 renders · 3 terms`.
//
// So the app captures its own evidence: patch `console.error` before React runs, match the loop's
// signature, and route everything — the args React passed (the component stack is among them) and the
// JS stack at the throw — to the FILE sink, which survives the renderer dying.

import { invoke } from "@tauri-apps/api/core";

/** React's wording for the loop. Matched loosely: the sentence has been stable across versions, but
 *  the surrounding punctuation has not. */
const LOOP_SIGNATURE = "Maximum update depth exceeded";

/** How many times to capture. A loop fires this error thousands of times per second; the first few
 *  carry the same stack as the thousandth, and writing all of them would flood the very log the
 *  evidence has to survive in — and add I/O to a thread that is already the bottleneck. */
export const MAX_CAPTURES = 3;

/** Truncation for one captured record. Long enough for a deep component stack, short enough that three
 *  of them cannot dominate a 10,000-line capped log. */
export const MAX_CAPTURE_CHARS = 8_000;

/** Everything worth keeping about one occurrence. Pure data so the formatting is testable. */
export interface RenderLoopCapture {
  message: string;
  /** React passes the component stack as a trailing argument; whichever arg looks like a stack wins. */
  componentStack: string;
  /** The JS call stack at the moment console.error ran — React internals plus the caller. */
  jsStack: string;
}

/** Whether these console.error arguments are the render-loop report. */
export function isRenderLoop(args: readonly unknown[]): boolean {
  return args.some((a) => typeof a === "string" && a.includes(LOOP_SIGNATURE));
}

/** A component stack looks like repeated `\n    at Name` / `\n    in Name` frames. React has used both
 *  spellings; matching either avoids depending on which one this version emits. */
export function looksLikeComponentStack(v: unknown): v is string {
  return typeof v === "string" && /\n\s*(at|in)\s+\S/.test(v);
}

/** Build the record from raw console.error arguments. Pure. */
export function captureFrom(args: readonly unknown[], jsStack: string): RenderLoopCapture {
  const strings = args.filter((a): a is string => typeof a === "string");
  return {
    message: strings.find((s) => s.includes(LOOP_SIGNATURE)) ?? LOOP_SIGNATURE,
    // The LAST stack-shaped argument: React appends the component stack after the message, and when
    // several arguments qualify the later one is the more specific.
    componentStack: [...args].reverse().find(looksLikeComponentStack) ?? "",
    jsStack,
  };
}

/** One log line carrying the whole capture. Truncated as a unit so a component stack cannot be cut in
 *  a way that hides the deepest frames — which are the ones that name the culprit. */
export function formatCapture(c: RenderLoopCapture, nth: number): string {
  const body = [
    `[render-loop] capture ${nth}/${MAX_CAPTURES} — ${c.message}`,
    c.componentStack ? `component stack:${c.componentStack}` : "component stack: (none in args)",
    c.jsStack ? `js stack:\n${c.jsStack}` : "js stack: (unavailable)",
  ].join("\n");
  return body.length > MAX_CAPTURE_CHARS ? `${body.slice(0, MAX_CAPTURE_CHARS)}\n…truncated` : body;
}

let installed = false;
let captures = 0;

/** Reset for tests. Not exported from the barrel — this is only for the suite. */
export function __resetForTest(): void {
  installed = false;
  captures = 0;
}

/**
 * Patch `console.error` to capture render loops. Call ONCE, as early as possible — before React, so
 * the very first occurrence is caught rather than the first one after mount.
 *
 * The original console.error is always called, unchanged and first: this observes, it never swallows.
 * A capture that suppressed the message would trade one blind spot for another.
 */
export function installRenderLoopCapture(): void {
  if (installed) return;
  installed = true;
  const original = console.error.bind(console);
  console.error = (...args: unknown[]) => {
    // The original ALWAYS runs, and runs first — so a throw in the capture below cannot cost the app
    // its error reporting.
    original(...args);
    if (captures >= MAX_CAPTURES || !isRenderLoop(args)) return;
    captures += 1;
    try {
      const jsStack = new Error("render-loop capture").stack ?? "";
      // SENT DIRECTLY, never through `log.error`.
      //
      // `log.error` pushes onto a queue drained by `setTimeout(drain, 250)`. A render loop PINS THE
      // MAIN THREAD, so that timer never fires and the capture dies with the renderer — the instrument
      // defeated by the exact condition it exists to observe. MEASURED 2026-08-31: after a renderer
      // death, the newest capture in the log was from a previous run; the one that had survived earlier
      // only did so because that loop happened to yield.
      //
      // `invoke` POSTS the IPC message synchronously (the promise resolves later, which does not
      // matter — nothing here awaits it), so the bytes leave the renderer before the next loop
      // iteration. The rejection is swallowed for the same reason the whole body is in a try/catch:
      // capturing evidence must never break the page it is diagnosing.
      //
      // Not going through the logger also removes the recursion risk entirely: `log.error` routes back
      // to `console.error` when its scope permits, which is this very function.
      void invoke("frontend_log", {
        level: "error",
        scope: "render-loop",
        message: formatCapture(captureFrom(args, jsStack), captures),
      }).catch(() => { /* the renderer is dying; there is nowhere left to report this */ });
    } catch {
      // Capturing evidence must never be the thing that breaks the page it is diagnosing.
    }
  };
}

