// The render-loop capture exists because vite forwards only the message and WebKitGTK has no
// inspector, so the component stack is otherwise unreachable. These pin the three things that make it
// useful rather than harmful: it MATCHES the loop, it is BOUNDED, and it cannot recurse.
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import {
  isRenderLoop,
  looksLikeComponentStack,
  captureFrom,
  formatCapture,
  installRenderLoopCapture,
  __resetForTest,
  MAX_CAPTURES,
  MAX_CAPTURE_CHARS,
} from "@/app/safety/renderLoopCapture";

const LOOP = "Maximum update depth exceeded. This can happen when a component calls setState…";
const STACK = "\n    at ConsolePane (http://127.0.0.1:1420/x.tsx:12:3)\n    at TerminalView";

describe("render-loop capture", () => {
  const original = console.error;
  beforeEach(() => {
    __resetForTest();
    console.error = original;
  });
  afterEach(() => {
    console.error = original;
  });

  it("matches the loop and nothing else", () => {
    expect(isRenderLoop([LOOP])).toBe(true);
    expect(isRenderLoop(["warning: something else"])).toBe(false);
    // React passes the message as one of several args, not always the first.
    expect(isRenderLoop([{}, LOOP, STACK])).toBe(true);
    expect(isRenderLoop([])).toBe(false);
    // A non-string arg must not throw the matcher.
    expect(isRenderLoop([null, undefined, 42])).toBe(false);
  });

  it("recognises a component stack by its frame shape, in either spelling", () => {
    expect(looksLikeComponentStack(STACK)).toBe(true);
    expect(looksLikeComponentStack("\n    in ConsolePane")).toBe(true); // React's older spelling
    expect(looksLikeComponentStack("just a message")).toBe(false);
    expect(looksLikeComponentStack(undefined)).toBe(false);
  });

  it("takes the LAST stack-shaped argument, which is the more specific one", () => {
    const earlier = "\n    at Root";
    const c = captureFrom([LOOP, earlier, STACK], "js");
    expect(c.componentStack).toBe(STACK);
    expect(c.message).toContain("Maximum update depth");
    expect(c.jsStack).toBe("js");
  });

  it("records the absence of a stack rather than inventing one", () => {
    const c = captureFrom([LOOP], "");
    expect(c.componentStack).toBe("");
    expect(formatCapture(c, 1)).toContain("(none in args)");
    expect(formatCapture(c, 1)).toContain("(unavailable)");
  });

  /// THE BOUND. A loop fires this thousands of times per second; writing all of them would flood the
  /// very log the evidence must survive in, on a thread that is already the bottleneck.
  it("captures at most MAX_CAPTURES times however often the loop fires", () => {
    const seen: string[] = [];
    console.error = vi.fn((...a: unknown[]) => {
      if (typeof a[0] === "string" && a[0].startsWith("[render-loop]")) seen.push(a[0]);
    }) as unknown as typeof console.error;
    installRenderLoopCapture();

    for (let i = 0; i < 500; i++) console.error(LOOP, STACK);

    // The capture goes straight to `invoke`, not to console, so assert on the counter's effect: the
    // patched function must stop doing work. Re-installing is also a no-op.
    installRenderLoopCapture();
    expect(seen.length).toBeLessThanOrEqual(MAX_CAPTURES);
  });

  /// It OBSERVES. A capture that swallowed the message would trade one blind spot for another.
  it("always calls the original console.error, first and unchanged", () => {
    const spy = vi.fn();
    console.error = spy as unknown as typeof console.error;
    installRenderLoopCapture();

    console.error(LOOP, STACK);
    expect(spy).toHaveBeenCalledWith(LOOP, STACK);

    console.error("an unrelated error", 1);
    expect(spy).toHaveBeenCalledWith("an unrelated error", 1);
    expect(spy).toHaveBeenCalledTimes(2);
  });

  it("truncates as a unit, and says that it did", () => {
    const huge = "\n    at C".repeat(5000);
    const out = formatCapture({ message: LOOP, componentStack: huge, jsStack: "x" }, 1);
    expect(out.length).toBeLessThanOrEqual(MAX_CAPTURE_CHARS + 16);
    expect(out).toContain("truncated");
  });

  it("installs once, so a second call cannot double-wrap the console", () => {
    const spy = vi.fn();
    console.error = spy as unknown as typeof console.error;
    installRenderLoopCapture();
    const afterFirst = console.error;
    installRenderLoopCapture();
    expect(console.error).toBe(afterFirst);

    // Double-wrapping would call the original twice per error.
    console.error("x");
    expect(spy).toHaveBeenCalledTimes(1);
  });

  /// THE FLAW THIS REPLACED. `log.error` queues behind `setTimeout(drain, 250)`, and a render loop
  /// pins the main thread so that timer never runs — the capture died with the renderer, which is the
  /// only case it exists for. It must reach `invoke` with NO timer in between.
  it("reaches the backend without waiting for a timer", () => {
    vi.useFakeTimers();                       // no timer is EVER advanced in this test
    try {
      console.error = vi.fn() as unknown as typeof console.error;
      installRenderLoopCapture();
      console.error(LOOP, STACK);

      // Sent already, with time frozen — a queued implementation would have sent nothing yet.
      expect(invoke).toHaveBeenCalledWith(
        "frontend_log",
        expect.objectContaining({ level: "error", scope: "render-loop" }),
      );
      const msg = (vi.mocked(invoke).mock.calls.at(-1)?.[1] as { message: string }).message;
      expect(msg).toContain("[render-loop] capture 1/3");
      expect(msg).toContain("ConsolePane");   // the component stack made it through
    } finally {
      vi.useRealTimers();
    }
  });

  /// A failed send must not break the page it is diagnosing.
  it("survives the backend being unreachable", () => {
    vi.mocked(invoke).mockRejectedValueOnce(new Error("no backend"));
    console.error = vi.fn() as unknown as typeof console.error;
    installRenderLoopCapture();
    expect(() => console.error(LOOP, STACK)).not.toThrow();
  });
});
